const item = $input.first().json;
let phone = '';
let text = '';
let phone_number_id = '';
let media_id = '';
let media_type = '';
let media_mime = '';
let media_caption = '';
try {
  if (item.messages && item.messages.length > 0) {
    const msg = item.messages[0];
    phone = String(msg.from || '');
    if (msg.type === 'text') {
      text = String((msg.text && msg.text.body) ? msg.text.body : '').trim();
    } else if (msg.type === 'interactive' && msg.interactive) {
      const it = msg.interactive;
      if (it.button_reply) {
        text = String(it.button_reply.id || it.button_reply.title || '').trim();
      } else if (it.list_reply) {
        text = String(it.list_reply.id || it.list_reply.title || '').trim();
      } else {
        text = '__media__';
      }
    } else if (msg.type === 'button' && msg.button) {
      text = String(msg.button.payload || msg.button.text || '').trim();
    } else {
      text = '__media__';
      const mm = msg[msg.type];
      if (mm && typeof mm === 'object') {
        media_id = String(mm.id || '');
        media_mime = String(mm.mime_type || '');
        media_caption = String(mm.caption || '');
        media_type = String(msg.type || '');
      }
    }
  }
  if (item.metadata) { phone_number_id = String(item.metadata.phone_number_id || ''); }
} catch(e) {}
if (!phone) return [];
return [{ json: { phone, text, phone_number_id, media_id, media_type, media_mime, media_caption } }];

const pd = $('Parse Message').first().json;
const phone = String(pd.phone || '');
const text = String(pd.text || '');
const pnid = String(pd.phone_number_id || '');

// client session row (from Load Session)
const rows = $input.all().map(i => i.json).filter(r => r && r.phone);
const sess = rows.length ? rows[0] : {};

// normalize arabic text (remove tashkeel, unify alef/ya/ha)
const norm = text
  .replace(/[\u064B-\u0652\u0640]/g, '')
  .replace(/[\u0623\u0625\u0622\u0671]/g, '\u0627')
  .replace(/\u0649/g, '\u064A')
  .replace(/\u0629/g, '\u0647')
  .toLowerCase();

let mode = 'normal';


return [{ json: { phone, text, phone_number_id: pnid, mode, norm, sess_step: String(sess.step||''), cart: String(sess.main_loads||'') } }];

// ===== Study Site: تحديد موقع المشروع (المدينة إحداثيات) لدراسة PVsyst =====
var sm = null; var origin = 'customer';
try { sm = $('State Machine').first().json; } catch (e) { sm = null; }
sm = sm || {};
const sp = sm.study_params || {};

// جدول المدن اليمنية الرئيسية (خط العرض/الطول/الارتفاع)
var CITIES = [
  { keys: ['صنعاء', 'صنعا', 'sanaa', "sana'a", 'sana', 'amanat'], en: 'Sanaa', lat: 15.3539, lon: 44.2059, alt: 2258 },
  { keys: ['عدن', 'aden'], en: 'Aden', lat: 12.7855, lon: 45.0187, alt: 6 },
  { keys: ['تعز', 'taiz', 'taizz'], en: 'Taiz', lat: 13.5789, lon: 44.0219, alt: 1311 },
  { keys: ['الحديدة', 'الحديده', 'حديدة', 'hodeidah', 'hudaydah', 'hodeida'], en: 'Al Hudaydah', lat: 14.7978, lon: 42.9545, alt: 12 },
  { keys: ['المكلا', 'مكلا', 'mukalla'], en: 'Al Mukalla', lat: 14.5425, lon: 49.1242, alt: 12 },
  { keys: ['إب', 'اب', 'ibb'], en: 'Ibb', lat: 13.9667, lon: 44.1833, alt: 2050 },
  { keys: ['ذمار', 'dhamar'], en: 'Dhamar', lat: 14.5427, lon: 44.4051, alt: 2400 },
  { keys: ['مأرب', 'مارب', 'marib', "ma'rib"], en: 'Marib', lat: 15.4623, lon: 45.3259, alt: 1120 },
  { keys: ['سيئون', 'سيون', 'seiyun', 'sayun'], en: 'Seiyun', lat: 15.943, lon: 48.7873, alt: 700 },
  { keys: ['حجة', 'حجه', 'hajjah'], en: 'Hajjah', lat: 15.6943, lon: 43.6055, alt: 1800 },
  { keys: ['عمران', 'amran'], en: 'Amran', lat: 15.6594, lon: 43.9439, alt: 2300 },
  { keys: ['صعدة', 'صعده', 'saada', "sa'dah"], en: 'Saada', lat: 16.9402, lon: 43.7637, alt: 1800 },
  { keys: ['البيضاء', 'البيضا', 'bayda', 'al bayda'], en: 'Al Bayda', lat: 13.9853, lon: 45.5735, alt: 2040 },
  { keys: ['لحج', 'lahij', 'lahj'], en: 'Lahij', lat: 13.0568, lon: 44.8811, alt: 130 },
  { keys: ['أبين', 'ابين', 'زنجبار', 'abyan', 'zinjibar'], en: 'Zinjibar', lat: 13.1283, lon: 45.3803, alt: 20 },
  { keys: ['شبوة', 'شبوه', 'عتق', 'shabwah', 'ataq'], en: 'Ataq', lat: 14.5377, lon: 46.8319, alt: 1150 },
  { keys: ['المحويت', 'mahwit'], en: 'Al Mahwit', lat: 15.4699, lon: 43.5451, alt: 2100 },
  { keys: ['الجوف', 'الحزم', 'jawf', 'hazm'], en: 'Al Hazm', lat: 16.1642, lon: 44.7769, alt: 1080 },
  { keys: ['الضالع', 'الضالع', 'dhale', 'dali'], en: 'Ad Dali', lat: 13.6957, lon: 44.7314, alt: 1500 },
  { keys: ['ريمة', 'ريمه', 'raymah'], en: 'Raymah', lat: 14.6277, lon: 43.7128, alt: 1900 },
  { keys: ['المهرة', 'الغيضة', 'mahra', 'ghaydah'], en: 'Al Ghaydah', lat: 16.2059, lon: 52.1758, alt: 20 },
  { keys: ['سقطرى', 'socotra', 'حديبو'], en: 'Hadibu', lat: 12.6508, lon: 54.0247, alt: 10 }
];

function norm(s) {
  return String(s || '').toLowerCase()
    .replace(/[\u064B-\u0652]/g, '')
    .replace(/[أإآ]/g, 'ا').replace(/ة/g, 'ه').replace(/ى/g, 'ي')
    .replace(/\s+/g, ' ').trim();
}
var cityText = norm(sp.city || '');
var site = null;
if (cityText) {
  for (var i = 0; i < CITIES.length && !site; i++) {
    for (var k = 0; k < CITIES[i].keys.length; k++) {
      if (cityText.indexOf(norm(CITIES[i].keys[k])) !== -1) { site = CITIES[i]; break; }
    }
  }
}
var siteMatched = !!site;
if (!site) { site = CITIES[0]; }

return [{ json: {
  site: { name: site.en, country: 'Yemen', lat: site.lat, lon: site.lon, alt: site.alt, tz: 'UTC+3', matched: !!siteMatched, raw_city: sp.city || '', fallback_weather_city: siteMatched ? '' : site.en },
  sp: sp,
  origin: origin,
  phone: sm.phone,
  phone_number_id: sm.phone_number_id
} }];

// ===== Study Prepare: محاكاة سنوية بمنهجية PVsyst للمنظومة المختارة =====
const siteItem = $('Study Site').first().json;
const site = siteItem.site;
const sp = siteItem.sp || {};
var pvgis = null;
try { pvgis = $input.first().json; } catch (e) { pvgis = null; }

// ---------- 1) بيانات المناخ الشهرية (PVGIS إن توفرت، وإلا جدول Meteonorm المدمج) ----------
var MONTHS = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];
var MON3 = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
var DAYS = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
var MIDDAY = [17, 47, 75, 105, 135, 162, 198, 228, 258, 288, 318, 344];

// قيم Meteonorm لصنعاء (من تقرير PVsyst المرجعي) — GlobHor / DiffHor kWh/m² ، T_Amb °C
var FALLBACK = {
  'Sanaa': { gh: [181.6, 180.3, 210.5, 200.7, 224.6, 206.7, 186.0, 190.1, 203.1, 213.8, 178.8, 175.4], dh: [38.7, 40.9, 51.5, 63.1, 63.7, 75.2, 84.5, 72.5, 60.0, 43.6, 41.0, 40.9], ta: [15.2, 17.1, 18.5, 19.9, 22.0, 23.6, 23.2, 22.4, 21.7, 18.0, 15.9, 14.4] },
  'Aden': { gh: [172.0, 175.0, 205.0, 205.0, 218.0, 205.0, 190.0, 195.0, 200.0, 205.0, 175.0, 165.0], dh: [45.0, 48.0, 60.0, 70.0, 75.0, 85.0, 90.0, 82.0, 68.0, 52.0, 45.0, 44.0], ta: [25.5, 25.8, 27.2, 29.0, 31.2, 32.8, 32.4, 31.7, 31.6, 29.0, 27.2, 26.0] },
  'Taiz': { gh: [178.0, 178.0, 208.0, 200.0, 215.0, 200.0, 182.0, 186.0, 196.0, 205.0, 176.0, 172.0], dh: [42.0, 45.0, 56.0, 66.0, 70.0, 80.0, 88.0, 78.0, 64.0, 48.0, 43.0, 42.0], ta: [19.5, 20.5, 22.0, 23.3, 24.8, 26.0, 25.5, 25.0, 24.5, 22.0, 20.0, 19.0] },
  'Al Hudaydah': { gh: [170.0, 172.0, 203.0, 205.0, 220.0, 208.0, 190.0, 192.0, 198.0, 205.0, 174.0, 165.0], dh: [46.0, 50.0, 62.0, 72.0, 78.0, 88.0, 92.0, 84.0, 70.0, 54.0, 46.0, 45.0], ta: [25.0, 25.5, 27.5, 29.5, 31.8, 33.5, 33.8, 33.2, 32.5, 29.8, 27.5, 25.8] },
  'Al Mukalla': { gh: [168.0, 172.0, 200.0, 205.0, 215.0, 198.0, 180.0, 185.0, 195.0, 200.0, 172.0, 162.0], dh: [44.0, 48.0, 60.0, 70.0, 78.0, 90.0, 95.0, 88.0, 70.0, 52.0, 44.0, 43.0], ta: [24.5, 25.0, 26.8, 28.8, 31.0, 32.5, 31.5, 30.8, 30.5, 28.0, 26.0, 25.0] }
};

var clim = { gh: [], dh: [], ta: [], source: '' };
try {
  var rows = pvgis && pvgis.outputs && Array.isArray(pvgis.outputs.monthly) ? pvgis.outputs.monthly : null;
  if (rows && rows.length >= 12) {
    var acc = [];
    for (var m0 = 0; m0 < 12; m0++) { acc.push({ gh: 0, kd: 0, ta: 0, n: 0 }); }
    rows.forEach(function (r) {
      var mi = Number(r.month) - 1;
      if (mi < 0 || mi > 11) { return; }
      var gh = Number(r['H(h)_m']); var kd = Number(r['Kd']); var ta = Number(r['T2m']);
      if (!isFinite(gh) || gh <= 0) { return; }
      acc[mi].gh += gh; acc[mi].kd += (isFinite(kd) ? kd : 0.25); acc[mi].ta += (isFinite(ta) ? ta : 20); acc[mi].n += 1;
    });
    var ok = acc.every(function (a) { return a.n > 0; });
    if (ok) {
      for (var m1 = 0; m1 < 12; m1++) {
        var gh1 = acc[m1].gh / acc[m1].n; var kd1 = acc[m1].kd / acc[m1].n;
        clim.gh.push(gh1); clim.dh.push(gh1 * kd1); clim.ta.push(acc[m1].ta / acc[m1].n);
      }
      var yrs = (pvgis.inputs && pvgis.inputs.meteo_data) ? (pvgis.inputs.meteo_data.year_min + '-' + pvgis.inputs.meteo_data.year_max) : '';
      clim.source = 'PVGIS-SARAH2 / ERA5' + (yrs ? ' (' + yrs + ')' : '') + ' - Monthly averages';
      if (pvgis.inputs && pvgis.inputs.location && isFinite(Number(pvgis.inputs.location.elevation))) { site.alt = Math.round(Number(pvgis.inputs.location.elevation)); }
    }
  }
} catch (e) { clim.gh = []; }
if (clim.gh.length !== 12) {
  var fb = FALLBACK[site.name] || FALLBACK['Sanaa'];
  clim = { gh: fb.gh.slice(), dh: fb.dh.slice(), ta: fb.ta.slice(), source: 'Meteonorm 8.1 (built-in monthly table) - Synthetic' };
}

// ---------- 2) Unified quotation-derived system configuration ----------
const U = $('Build System Configuration').first().json || {};
const UC = U.system_config || {};
if(!UC.validation || !UC.validation.ok){ throw new Error('PVsyst aborted: quotation-derived System Configuration is invalid: '+String((UC.validation&&UC.validation.errors||U.system_config_errors||[]).join('; '))); }
const QSYS = UC.system;
const kind = String(QSYS.systemType||'Residential').toLowerCase().indexOf('commercial')>=0 ? 'com' : 'res';
const sysMode = QSYS.sysMode || (QSYS.inv&&QSYS.inv.hybrid ? 'hyb' : '');
const gridTied = (QSYS.grid === true || sysMode === 'on' || sysMode === 'hyb');
const PAN = QSYS.panel;
const INV = QSYS.inv;
const BAT = QSYS.bat || {kwh:0,dod:0,v:0,ah:0};
const nPan = Number(QSYS.nPan)||0;
const nInv = Number(QSYS.nInv)||0;
const nBat = Number(QSYS.nBat)||0;
const kWp = Number(QSYS.kWp)||0;
const kWac = Number(QSYS.kWac)||0;
const batKwh = Number(BAT.kwh||0)*nBat;
const batUsable = BAT.usableKwh>0 ? Number(BAT.usableKwh)*nBat : (BAT.dod>0 ? batKwh*BAT.dod/100 : 0);
const loadDaily = Number(sp.load_daily || sp.load || 0);
const dayPct = Number(sp.day_pct || 0);
const strings = {n:Number(QSYS.nStr||0),s:0};
if(strings.n>0 && Number(QSYS.perStr||0)>0) strings.s=Number(QSYS.perStr);
// No string configuration is invented. If the quotation only contains module count, PVsyst reports strings as unavailable.

// ---------- 3) Engineering inputs and loss-chain policy ----------
var lat = Number(site.lat); var latR = lat * Math.PI / 180;
var tilt = Number(sp.tilt); if(!(tilt>0)) tilt=Math.max(10,Math.min(30,Math.round(Math.abs(lat))));
var tiltR = tilt * Math.PI / 180;
var azimuth = Number(sp.azimuth); if(!isFinite(azimuth)) azimuth=0; // 0 = South in this report convention
var albedo = Number(sp.albedo); if(!(albedo>=0 && albedo<=1)) albedo=0.20;

// Only source-backed or physically derived losses are applied. Missing loss inputs are zero/NA, not fabricated.
var LOSS = {soiling:0, iam:0, shading:0, irrLevel:0, quality:0, lid:0, mismatch:0, ohmic:0, nightCons:0, unavail:0, chargerLoss:0, battEff:0, invOut:0};
var LOSS_SRC = {};
function sourcePct(key, re){
  for(var si=0;si<UC.source_items.length;si++){
    var stx=String(UC.source_items[si].description||UC.source_items[si].name||'');
    var mm=stx.match(re); if(mm){ var v=Number(String(mm[1]).replace(',','.')); if(isFinite(v)) return v; }
  }
  return null;
}
var vSoil=sourcePct('soiling',/soiling|اتساخ|غبار/i); if(vSoil!=null){LOSS.soiling=vSoil;LOSS_SRC.soiling='quotation';}
var vLid=sourcePct('lid',/\bLID\b/i); if(vLid!=null){LOSS.lid=vLid;LOSS_SRC.lid='quotation';}
var vMis=sourcePct('mismatch',/mismatch|عدم\s*التطابق/i); if(vMis!=null){LOSS.mismatch=vMis;LOSS_SRC.mismatch='quotation';}
var vOhm=sourcePct('ohmic',/ohmic|أومي/i); if(vOhm!=null){LOSS.ohmic=vOhm;LOSS_SRC.ohmic='quotation';}
var etaInv = Number(INV.eff)||0;
if(etaInv>0){LOSS_SRC.inverter_efficiency='quotation';}
var bifGain = (PAN && PAN.bifacial && Number(PAN.bifaciality)>0) ? Number(PAN.bifaciality)*2 : 0;
var pnomRatio = kWp>0&&kWac>0 ? kWp/kWac : 0;
var clipLoss = 0; // clipping requires hourly irradiance and inverter operating envelope; never fabricated from a DC/AC threshold.

function deg2rad(d) { return d * Math.PI / 180; }
var monthly = [];
var Y = { gh:0,dh:0,ginc:0,geff:0,earr:0,eavail:0,euser:0,esolar:0,egrid:0,efrgrid:0,eunused:0,load:0,direct:0,batIn:0,batOut:0 };
var taSum=0;
for(var m=0;m<12;m++){
  var H=clim.gh[m], D=Math.min(clim.dh[m],H*0.9), Ta=clim.ta[m], nd=DAYS[m];
  var decl=deg2rad(23.45*Math.sin(2*Math.PI*(284+MIDDAY[m])/365));
  var ws=Math.acos(Math.max(-1,Math.min(1,-Math.tan(latR)*Math.tan(decl))));
  var wsT=Math.min(ws,Math.acos(Math.max(-1,Math.min(1,-Math.tan(latR-tiltR)*Math.tan(decl)))));
  var den=(Math.cos(latR)*Math.cos(decl)*Math.sin(ws)+ws*Math.sin(latR)*Math.sin(decl));
  var Rb=den!==0?((Math.cos(latR-tiltR)*Math.cos(decl)*Math.sin(wsT)+wsT*Math.sin(latR-tiltR)*Math.sin(decl))/den):1;
  var Ginc=(H-D)*Rb + D*(1+Math.cos(tiltR))/2 + H*albedo*(1-Math.cos(tiltR))/2;
  var Geff=Ginc*(1-LOSS.shading/100)*(1-LOSS.soiling/100)*(1-LOSS.iam/100);
  var Gcoll=Geff*(1+bifGain/100);
  var dayHours=Math.max(1,2*ws*180/Math.PI/15);
  var Gmean=Ginc*1000/(nd*dayHours); var Gw=Gmean*1.6;
  var modEff=Number(PAN.eff)||0;
  var alphaAbs=modEff>0?0.9*(1-modEff/100):0.9;
  var Tc=Ta+alphaAbs*Gw/29;
  var tempLoss=(Number(PAN.gamma)||0)*(Tc-25);
  var EnomArr=Gcoll*kWp;
  var f=(1-LOSS.irrLevel/100)*(1+tempLoss/100)*(1-LOSS.quality/100)*(1-LOSS.lid/100)*(1-LOSS.mismatch/100)*(1-LOSS.ohmic/100);
  var EArr=EnomArr*f;
  var Eac=etaInv>0?EArr*(etaInv/100)*(1-clipLoss/100)*(1-LOSS.nightCons/100)*(1-LOSS.unavail/100):null;
  // Without an actual load profile, do not fabricate monthly self-consumption or battery dispatch.
  var hasLoadProfile = loadDaily > 0;
  var euser=(Eac==null||!hasLoadProfile)?null:Eac, egrid=0, unused=hasLoadProfile?0:null, missing=hasLoadProfile?0:null, direct=hasLoadProfile?0:null, chargeIn=hasLoadProfile?0:null, stored=0, discharged=hasLoadProfile?0:null;
  var row={name:MONTHS[m],mon:MON3[m],days:nd,globHor:H,diffHor:D,tAmb:Ta,globInc:Ginc,globEff:Geff,gColl:Gcoll,eArray:EArr,eAvail:Eac,eUser:euser==null?null:euser*nd,eSolar:euser==null?null:euser*nd,eGrid:egrid,eFrGrid:null,eUnused:unused,load:null,direct:direct,batIn:chargeIn,batOut:discharged,tc:Tc,tempLoss:tempLoss,Rb:Rb,Yr:Ginc/nd,Ya:EArr/kWp/nd,Yf:Eac==null?null:Eac/kWp/nd};
  row.Lc=row.Yr-row.Ya; row.Ls=row.Ya-(row.Yf==null?0:row.Yf); row.PR=row.Yf==null?null:row.Yf/row.Yr; row.SF=null;
  monthly.push(row);
  Y.gh+=H;Y.dh+=D;Y.ginc+=Ginc;Y.geff+=Geff;Y.earr+=EArr;if(Eac!=null){Y.eavail+=Eac;if(hasLoadProfile){Y.euser+=euser*nd;Y.esolar+=euser*nd;}}taSum+=Ta;
}
Y.ta=taSum/12;
var year={globHor:Y.gh,diffHor:Y.dh,tAmb:Y.ta,globInc:Y.ginc,globEff:Y.geff,eArray:Y.earr,eAvail:(etaInv>0?Y.eavail:null),eUser:(etaInv>0&&loadDaily>0?Y.euser:null),eSolar:(etaInv>0&&loadDaily>0?Y.esolar:null),eGrid:null,eFrGrid:null,eUnused:null,load:null,direct:null,batIn:null,batOut:null,PR:(etaInv>0&&Y.ginc>0&&kWp>0)?Y.eavail/(Y.ginc*kWp):null,SF:null,specific:(etaInv>0&&kWp>0)?Y.eavail/kWp:null,bifPR:(etaInv>0&&Y.ginc>0&&kWp>0)?Y.eavail/(Y.ginc*kWp*(1+bifGain/100)):null};
var tempYear=monthly.reduce(function(a,r){return a+r.tempLoss*r.gColl;},0)/Math.max(1,monthly.reduce(function(a,r){return a+r.gColl;},0));
var lossDiagram={globHor:Y.gh,incidentPct:(Y.ginc/Y.gh-1)*100,shading:-LOSS.shading,soiling:-LOSS.soiling,iam:-LOSS.iam,groundRefl:albedo*(1-Math.cos(tiltR))/2*100,bifacial:bifGain,effIrr:Y.geff*(1+bifGain/100),collArea:Number(PAN.area||0)*nPan,eff:Number(PAN.eff||0),eNom:Y.geff*(1+bifGain/100)*kWp,irrLevel:-LOSS.irrLevel,temp:tempYear,quality:-LOSS.quality,lid:-LOSS.lid,mismatch:-LOSS.mismatch,ohmic:-LOSS.ohmic,eArray:Y.earr,invOp:etaInv>0?-(100-etaInv):null,invClip:clipLoss? -clipLoss:null,eInvOut:etaInv>0?Y.eavail:null,unavail:-LOSS.unavail,eAvail:etaInv>0?Y.eavail:null,unused:null,chargerLoss:null,battLoss:null,invOut:null,directPct:null,storedPct:null,eUser:etaInv>0?Y.euser:null,eFrGrid:null,eGrid:null};

// ---------- 3) الهندسة الشمسية والتحويل إلى مستوى الألواح ----------
// ---------- 4) روابط الرسوم البيانية (QuickChart) ----------
function r2(v) { return Math.round(v * 100) / 100; }
function r3(v) { return Math.round(v * 1000) / 1000; }
var labels = MON3;
var chNorm = {
  type: 'bar',
  data: { labels: labels, datasets: [
    { label: 'Yf: Produced useful energy (inverter output) ' + r2(year.eAvail / kWp / 365) + ' kWh/kWp/day', data: monthly.map(function (r) { return r3(r.Yf); }), backgroundColor: '#7b1fa2' },
    { label: 'Ls: System Loss (inverter, ...) ' + r2(monthly.reduce(function (a, r) { return a + r.Ls * r.days; }, 0) / 365) + ' kWh/kWp/day', data: monthly.map(function (r) { return r3(r.Ls); }), backgroundColor: '#2e7d32' },
    { label: 'Lc: Collection Loss (PV-array losses) ' + r2(monthly.reduce(function (a, r) { return a + r.Lc * r.days; }, 0) / 365) + ' kWh/kWp/day', data: monthly.map(function (r) { return r3(r.Lc); }), backgroundColor: '#c62828' }
  ] },
  options: { title: { display: true, text: 'Normalized productions (per installed kWp)', fontSize: 14 }, legend: { position: 'top', labels: { fontSize: 9, boxWidth: 12 } },
    scales: { xAxes: [{ stacked: true, gridLines: { display: false } }], yAxes: [{ stacked: true, ticks: { beginAtZero: true, max: 9 }, scaleLabel: { display: true, labelString: 'Normalized Energy [kWh/kWp/day]' } }] } }
};
var chPR = {
