function dailyProductionFromItems(items) {
  var total = 0;
  for (var i = 0; i < items.length; i++) {
    if (String(items[i][0]).indexOf('panel:') === 0) {
      var panelW = parseFloat(String(items[i][0]).split(':')[1]) || 0;
