// الضمان مسموح لصنفين فقط: الألواح 25 سنة، والبطاريات 5 سنوات.
(function enforceWarrantyPolicy() {
  function cleanWarrantyText(s, allowed) {
    var x = String(s || '');
    x = x.replace(/\s*\|?\s*ضمان[^|،؛]*?/ig, function (m) {
      return '';
    });
    x = x.replace(/\s*\|?\s*الضمان[^|،؛]*?/ig, '');
    x = x.replace(/\s{2,}/g, ' ').replace(/\|\s*\|/g, '|').trim();
    var warranty = allowed === 'panel' ? 'الضمان: 25 سنة' : (allowed === 'battery' ? 'الضمان: 5 سنوات' : '');
    if (warranty) {
      var certPos = x.search(/\|\s*الشهادات\s*:/i);
      if (certPos >= 0) {
        x = x.slice(0, certPos).replace(/\s*\|\s*$/, '') + ' | ' + warranty + ' ' + x.slice(certPos);
      } else {
        x += (x ? ' | ' : '') + warranty;
      }
    }
    return x;
  }
  for (var wi = 0; wi < q.items.length; wi++) {
    var wit = q.items[wi];
    var wk = String((wit && wit.key) || '');
    var wt = String((wit && (wit.description || wit.name)) || '');
    var isPanel = /^panel[:]/i.test(wk) || /(?:لوح|ألواح|الواح)\s*(?:طاقة|شمسية)|PV\s*module/i.test(wt);
    var isBattery = /^(?:battery|ess)[:]/i.test(wk) || /بطاري/i.test(wt);
    wit.description = cleanWarrantyText(wt, isPanel ? 'panel' : (isBattery ? 'battery' : 'other'));
  }
})();

// استبعاد قواعد/هياكل تثبيت الألواح من عرض السعر
(function stripPanelBase() {
  if (!q || !q.items) { return; }
  var removed = 0;
  var kept = [];
  for (var bi = 0; bi < q.items.length; bi++) {
    var bit = q.items[bi];
    var btxt = String((bit && (bit.description || bit.name)) || '');
    var bkey = String((bit && bit.key) || '');
    if (bkey === 'base:3m' || /(قاعدة|قواعد|هيكل|هياكل|حوامل)\s*(\/\s*هيكل\s*)?(تثبيت\s*)?(ال)?[أا]لواح/.test(btxt)) {
      removed += parseFloat(String(bit.total).replace(/,/g, '')) || 0;
      continue;
    }
    bit.index = kept.length + 1;
    kept.push(bit);
  }
  if (removed > 0 || kept.length !== q.items.length) {
    q.items = kept;
    var tt = parseFloat(String(q.total).replace(/,/g, '')) || 0;
    q.total = Math.max(0, tt - removed);
  }
})();


