  if(isDcProt(a)){ const x=firstNum(a,/قاطع\s*تيار\s*مستمر[^|]*?(\d+(?:[.,]\d+)?)\s*امبير/i)||firstNum(a,/MCB[^|]*?(\d+(?:[.,]\d+)?)\s*A(?:H)?/i)||firstNum(a,/DC[^|]*?(\d+(?:[.,]\d+)?)\s*A/i); if(x&&!dcBreakerA) dcBreakerA=x; const f=firstNum(a,/فيوز[^|]*?(\d+(?:[.,]\d+)?)\s*امبير/i); if(f&&!dcFuseA) dcFuseA=f; const cm=firstNum(a,/(?:كابل|cable)[^|]*?(\d+(?:[.,]\d+)?)\s*(?:مم|mm)/i); if(cm&&!dcCableMm) dcCableMm=cm; if(/SPD/i.test(a)) hasDcSpd=true; if(/فاصل|isolator/i.test(a)) hasDcIsolator=true; }
  if(isAcProt(a)){ const x=firstNum(a,/قاطع\s*تيار\s*متردد[^|]*?(\d+(?:[.,]\d+)?)\s*امبير/i)||firstNum(a,/MCB[^|]*?(\d+(?:[.,]\d+)?)\s*A(?:H)?/i)||firstNum(a,/AC[^|]*?(\d+(?:[.,]\d+)?)\s*A/i); if(x&&!acBreakerA) acBreakerA=x; const cm=firstNum(a,/(?:كابل|cable)[^|]*?(\d+(?:[.,]\d+)?)\s*(?:مم|mm)/i); if(cm&&!acCableMm) acCableMm=cm; if(/SPD/i.test(a)) hasAcSpd=true; if(/فاصل|isolator/i.test(a)) hasAcIsolator=true; if(/رئيسي|main/i.test(a)&&x&&!mainBreakerA) mainBreakerA=x; }
