}

const systemType = meta.quote_flow==='commercial'||meta.menu_choice==='2' ? 'Commercial' : (meta.quote_flow==='pv' ? 'PV Study' : 'Residential');
if(!phase && inv && inv.phase) phase=inv.phase;
if(!phase) phase = String(meta.phase_type||'').toLowerCase()==='three' ? 'Three Phase' : (String(meta.phase_type||'').toLowerCase()==='single' ? 'Single Phase' : '');
const sysModeRaw=String(meta.sys_mode||'').toLowerCase();
let sysMode = sysModeRaw==='on'?'on':(sysModeRaw==='off'?'off':'');
if(!sysMode){ if(inv&&inv.hybrid){ sysMode='hyb'; } else if(grid===true && !backup){ sysMode='on'; } else if(!grid && !backup){ sysMode=''; } }
if(sysMode==='hyb'||sysMode==='off') backup=true;
if(sysMode==='on') grid=true;

// Derive only quantities that are mathematically certain from source data.
const installedDcKw = (nModules>0 && panel && panel.wp>0) ? nModules*panel.wp/1000 : 0;
const totalAcKw = (nInv>0 && inv && inv.kwac>0) ? nInv*inv.kwac : 0;
const dcAcRatio = installedDcKw>0&&totalAcKw>0 ? installedDcKw/totalAcKw : 0;
if(!nStrings && items.some(it=>/^dc:/i.test(String(it.key||'')))) nStrings=items.reduce((a,it)=>a+(/^dc:(\d+)/i.test(String(it.key||''))?firstNum(String(it.key||''),/^dc:(\d+)/i):0),0);
if(nStrings===0 && nModules===1) nStrings=1;
const perString = (nStrings>0 && nModules>0 && nModules % nStrings === 0) ? (nModules/nStrings) : 0;

function complexity(){ let s=0; if(systemType==='Commercial')s+=2; if(nInv>1)s+=2; if(nModules>12)s+=2; if(nStrings>4)s+=1; if(inv&&inv.mppt>2)s+=1; if(transformer)s+=3; if(voltageLevel==='Medium/High Voltage')s+=3; if(backup)s+=1; if(nBat>1)s+=1; return s; }
const score=complexity();
const model = (voltageLevel==='Medium/High Voltage'||transformer||nModules>40||totalAcKw>=30||nInv>=3) ? 'LARGE' : ((systemType==='Commercial'||nInv>1||nModules>24||nStrings>4||totalAcKw>=20) ? 'MEDIUM' : 'SMALL');

const errors=[];
if(!qn) errors.push('quote_number missing');
if(!items.length) errors.push('quotation source items missing');
if(!panel || !panel.wp || !nModules) errors.push('PV module quantity/power missing from quotation');
if(!inv || !inv.kwac || !nInv) errors.push('inverter quantity/power missing from quotation');
if(nBat>0 && (!bat || !bat.kwh)) errors.push('battery quantity/capacity incomplete in quotation');
if(installedDcKw && panel.wp && Math.abs(installedDcKw-(nModules*panel.wp/1000))>1e-9) errors.push('DC power consistency failure');
if(totalAcKw && Math.abs(totalAcKw-(nInv*inv.kwac))>1e-9) errors.push('AC power consistency failure');

const sld={
  quote_number:qn, project:meta.customer_name||sm.customer_name||'', city_en:meta.city||sm.city||'', date:new Date().toISOString().slice(0,10), ref:qn||'ACTES-SLD',
  model, systemType, sysMode, sysLabel:systemType+' / '+model,
  phase3:phase==='Three Phase', phase, voltageLevel, grid:!!grid, backup:!!backup,
  panel:Object.assign({maker:'',model:'',wp:0,eff:0,area:0,bifacial:false,bifaciality:0,gamma:0,voc:0,vmp:0,imp:0,isc:0},panel||{}),
  inv:Object.assign({maker:'',model:'',kwac:0,mppt:0,phase:phase,vdc:'',eff:0,vbat:0},inv||{}),
  bat:Object.assign({model:'',kwh:0,v:0,dod:0},bat||{}), batKey:'', batName:bat&&bat.model||'',
  nPan:nModules,nInv:nInv,nBat:nBat,nStr:nStrings,perStr:perString,mppt:inv&&inv.mppt?inv.mppt*nInv:0,
  kWp:installedDcKw,kWac:totalAcKw,pnomRatio:dcAcRatio,
  dcProtection:{breakerA:dcBreakerA,fuseA:dcFuseA,isolator:hasDcIsolator,spd:hasDcSpd,cableMm:dcCableMm},
  acProtection:{breakerA:acBreakerA,mainBreakerA:mainBreakerA,isolator:hasAcIsolator,spd:hasAcSpd,cableMm:acCableMm},
  transformer:transformer, grounding:hasGround,
  source:'Official quotation items persisted by State Machine', sourceItems:sourceItems,
  derived:{installedDcKw:'Number of modules × module W / 1000',totalAcKw:'Number of inverters × inverter kW',dcAcRatio:'Installed DC / total AC'},
  stringDistribution: perString>0 ? 'exact' : (nStrings>0 ? 'group count known; modules per string not specified' : 'not available'),
  dataStatus:{panelModel:!!(panel&&panel.model),modulePower:!!(panel&&panel.wp),inverterModel:!!(inv&&inv.model),mppt:!!(inv&&inv.mppt),strings:!!nStrings,battery:nBat>0,transformer:!!transformer}
};

const config={version:1,quote_number:qn,source_type:'quotation',source_items:sourceItems,system:sld,installedDcKw,totalAcKw,dcAcRatio,model,validation:{ok:errors.length===0,errors:errors}};
return [{json:{...sm,system_config:config,system_config_valid:errors.length===0,system_config_errors:errors}}];
